import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:keywallet_multios/core/crypto/kwv1_crypto.dart';

// Generated by the actual Go KeyWallet 0.1.4 encryptBlob() implementation.
// Password: go-flutter-fixture
// Revision: 42
const _go014Fixture =
    '';

void main() {
  test('decrypts a vault produced by Go KeyWallet 0.1.4', () async {
    final opened = await Kwv1Crypto.decrypt(
      base64Decode(_go014Fixture),
      'go-flutter-fixture',
    );

    expect(opened.container.iterations, 1000);
    expect(opened.container.revision, 42);
    expect(opened.vault.version, 1);

    final git = opened.vault.root.children.single;
    expect(git.name, 'GIT');
    final entry = git.children.single;
    expect(entry.kind, 'github-ssh');
    expect(entry.meta['algorithm'], 'Ed25519');
    expect(entry.meta['comment'], 'fixture@example.com');
    expect(entry.files.length, 2);
    expect(
      utf8.decode(entry.files.first.data),
      'ssh-ed25519 AAAATEST fixture@example.com\n',
    );
    expect(utf8.decode(entry.files.last.data), 'PRIVATE-FIXTURE');
  });
}
